/// Returns the larger of two values.
///
/// # Examples
/// ```
/// use lesson_docs::larger;
/// assert_eq!(larger(2, 7), 7);
/// ```
pub fn larger(a: i32, b: i32) -> i32 {
    if a > b { a } else { b }
}

